findings.codeql_raw_query:
/**
 * @name Untrusted input to subprocess and shell execution in virtualenv
 * @description Detects flows from remote/user-controlled input (CLI, env vars, config) into subprocess or shell execution APIs.
 * @kind path-problem
 * @problem.severity error
 * @id py/virtualenv-subprocess-taint
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module SubprocessTaintConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      sink = call and
      (
        call = API::moduleImport("subprocess").getMember(["Popen", "call", "run", "check_call", "check_output"]).getACall() or
        call = API::moduleImport("os").getMember(["system", "popen"]).getACall()
      )
    )
  }
}

module SubprocessTaintFlow = TaintTracking::Global<SubprocessTaintConfig>;
import SubprocessTaintFlow::PathGraph

from SubprocessTaintFlow::PathNode source, SubprocessTaintFlow::PathNode sink
where SubprocessTaintFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data reaches subprocess or shell execution $@.", source.getNode(), "user input"
